import{_ as e,o as r,c as d,ag as i}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"GC victim 선택 정책 비교 — Greedy(vpc) vs FIFO(write_seq)","description":"","frontmatter":{},"headers":[{"level":2,"title":"목적","slug":"목적","link":"#목적","children":[]},{"level":2,"title":"검증 방법","slug":"검증-방법","link":"#검증-방법","children":[]},{"level":2,"title":"결과","slug":"결과","link":"#결과","children":[{"level":3,"title":"순차 쓰기 (Seq)","slug":"순차-쓰기-seq","link":"#순차-쓰기-seq","children":[]},{"level":3,"title":"랜덤 쓰기 (Random)","slug":"랜덤-쓰기-random","link":"#랜덤-쓰기-random","children":[]}]},{"level":2,"title":"결론","slug":"결론","link":"#결론","children":[]}],"relativePath":"computer/Research/URA/results/02 virt_fifo_GC (Greedy vs FIFO) 실험 결과.md","filePath":"computer/Research/URA/results/02 virt_fifo_GC (Greedy vs FIFO) 실험 결과.md"}'),a={name:"computer/Research/URA/results/02 virt_fifo_GC (Greedy vs FIFO) 실험 결과.md"};function l(o,t,n,s,c,_){return r(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="gc-victim-선택-정책-비교-—-greedy-vpc-vs-fifo-write-seq" tabindex="-1">GC victim 선택 정책 비교 — Greedy(vpc) vs FIFO(write_seq) <a class="header-anchor" href="#gc-victim-선택-정책-비교-—-greedy-vpc-vs-fifo-write-seq" aria-label="Permalink to &quot;GC victim 선택 정책 비교 — Greedy(vpc) vs FIFO(write_seq)&quot;">​</a></h1><h2 id="목적" tabindex="-1">목적 <a class="header-anchor" href="#목적" aria-label="Permalink to &quot;목적&quot;">​</a></h2><p>기존 Greedy(vpc 기준) victim 선택이 순차 쓰기 조건에서 결과적으로 FIFO처럼 동작한다는 가설을 검증하고, 랜덤 쓰기에서 두 정책의 실제 차이를 측정한다.</p><h2 id="검증-방법" tabindex="-1">검증 방법 <a class="header-anchor" href="#검증-방법" aria-label="Permalink to &quot;검증 방법&quot;">​</a></h2><ul><li><code>struct line</code>에 <code>write_seq</code>(몇 번째로 마감됐는지) 필드 추가, line이 가득 찰 때마다 전역 카운터로 순번 부여</li><li><code>#define GC_POLICY_FIFO</code> 매크로로 victim 우선순위 기준을 vpc(Greedy) ↔ write_seq(FIFO)로 전환</li><li>GC 시마다 victim의 <code>write_seq</code>를 로그로 남겨, victim 선택 순서가 오름차순(역전 없음)인지 확인</li></ul><p><strong>환경</strong>: <code>NAND_CHANNELS=1, LUNS_PER_NAND_CH=1</code>, <code>memmap_size=32G</code>, precondition 후 <code>seq_gc_invoke</code>/<code>rand_gc_invoke</code> (<code>--bs=256k --size=3000M</code>)</p><h2 id="결과" tabindex="-1">결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;">​</a></h2><h3 id="순차-쓰기-seq" tabindex="-1">순차 쓰기 (Seq) <a class="header-anchor" href="#순차-쓰기-seq" aria-label="Permalink to &quot;순차 쓰기 (Seq)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>Greedy(vpc)</th><th>FIFO</th></tr></thead><tbody><tr><td>gc_count</td><td>218</td><td>218</td></tr><tr><td>write_seq 순서</td><td>완전 오름차순</td><td>완전 오름차순</td></tr><tr><td>clat p99 / p99.9 / max (us)</td><td>5211 / 5342 / 5320</td><td>5211 / 5211 / 5286</td></tr><tr><td>이상값</td><td>없음</td><td>없음</td></tr></tbody></table><p>동일한 GC 발생 횟수·선택 순서 패턴·거의 동일한 latency 분포 — <strong>순차 쓰기 조건에서는 Greedy와 FIFO가 사실상 동일하게 동작</strong>한다는 가설 확인.</p><p>![[seq_greedy_lat.png]]<br> ![[seq_fifo_lat.png]]</p><h3 id="랜덤-쓰기-random" tabindex="-1">랜덤 쓰기 (Random) <a class="header-anchor" href="#랜덤-쓰기-random" aria-label="Permalink to &quot;랜덤 쓰기 (Random)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>Greedy</th><th>FIFO</th></tr></thead><tbody><tr><td>gc_count</td><td>218</td><td><strong>255</strong></td></tr><tr><td>free_line_cnt(최종)</td><td>3</td><td>2</td></tr><tr><td>victim_line_cnt</td><td>532</td><td>533</td></tr><tr><td>write_seq 순서</td><td>불규칙(무작위)</td><td>완전 오름차순</td></tr><tr><td>clat p99 / p99.9 / max (us)</td><td>5211 / 5276 / 5323</td><td><strong>10028 / 22152 / 31693</strong></td></tr></tbody></table><ul><li><strong>Greedy</strong>: 그 순간의 vpc(valid page 개수)만 보고 victim을 고르므로, write 패턴이 순차든 랜덤이든 GC 총량·최종 free space가 동일하게 유지됨</li><li><strong>FIFO</strong>: write 패턴과 무관하게 &quot;가장 먼저 채워진 line&quot;을 기계적으로 선택 — 아직 valid 데이터가 많이 남은 line도 그대로 victim이 되어, 매 GC마다 옮겨야 할 데이터가 Greedy보다 커짐 → 동일 write량에서 GC가 <strong>218회 → 255회로 증가</strong></li></ul><p>![[rand_greedy_lat.png]]<br> ![[rand_fifo_lat.png]]</p><p>Random·FIFO는 15초 이후 latency가 8000~30000us 범위에서 넓게 산개하며 스파이크 폭이 Random·Greedy보다 훨씬 크고 불규칙함.</p><h2 id="결론" tabindex="-1">결론 <a class="header-anchor" href="#결론" aria-label="Permalink to &quot;결론&quot;">​</a></h2><ul><li><strong>순차 쓰기</strong>: Greedy(vpc)와 FIFO(write_seq)가 사실상 동일한 line을 선택 — 차이가 드러나지 않음</li><li><strong>랜덤 쓰기</strong>: Greedy는 워크로드 패턴과 무관하게 &quot;정리 비용이 가장 싼 line&quot;을 우선하므로 GC 총량이 안정적(218회 유지). FIFO는 정리 비용을 고려하지 않고 오래된 순서만 따르므로, 랜덤 쓰기에서 valid 데이터가 많이 남은 line을 GC하게 되는 경우가 늘어 <strong>GC 횟수(255회)와 tail latency(최대 31.7ms, Greedy 대비 약 6배) 모두 크게 증가</strong></li><li>FIFO는 &quot;정리 비용을 고려하지 않는다&quot;는 특성이 랜덤 워크로드에서 직접적인 성능 저하로 드러남을 확인</li></ul>',18)])])}const p=e(a,[["render",l]]);export{u as __pageData,p as default};
